scripts.紫轩对话.txt:
	If ($Event == 144) @Label1;
	If ($Event == 170) @Label2;
	Goto @end;
	
@Label1:
	If ($ZiXuanSense >> 20) @AddSenseEnd;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd:	
	Talk(2083, 2084);
	Goto @end;
	
@Label2:	
	If ($Talkzx021 == 0) @Talk0;
	If ($Talkzx021 == 1) @Talk1;
	Goto @end;
@Talk0:
	If ($ZiXuanSense >> 20) @AddSenseEnd2;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd2:
	Say("紫轩：杨大哥，你说我傻，其实我何尝不知道你对我的心意……", 17);
	Say("杨影枫：你既知道我的心意，就应该明白，无论为你做什么我都是心甘情愿的！如果你有难，我岂会袖手旁观？", 3);
	Assign($Talkzx021, 1);
	Return;
@Talk1:
	If ($ZiXuanSense >> 20) @AddSenseEnd3;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd3:
	Say("杨影枫：紫轩，如果你有难，我岂会袖手旁观？", 2);
	Say("紫轩：杨大哥 ……", 17);
	Return;	
	
	
@end:	
	Return;

