	FullThew();
	FullMana();
	PlayMusic("mc013.mp3");
	FadeIn();
	Say("杨影枫：天终于亮了。", 2);
	PlayerRunTo(24, 94);
	SetPlayerDir(7);
	Say("杨影枫：紫轩会不会已经在樱花谷等我了？我此刻就去见她！", 2);
	Memo("去樱花谷见紫轩。");
